import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "entitySearch", label: "Search", type: "text", value: "", attrs: "placeholder=\"Search entities...\"" })}</div>`,generate(root) {const entities = [{ char: "©", entity: "&amp;copy;", name: "Copyright", category: "Symbols" },{ char: "®", entity: "&amp;reg;", name: "Registered", category: "Symbols" },{ char: "™", entity: "&amp;trade;", name: "Trademark", category: "Symbols" },{ char: "—", entity: "&amp;mdash;", name: "Em Dash", category: "Dashes" },{ char: "–", entity: "&amp;ndash;", name: "En Dash", category: "Dashes" },{ char: "…", entity: "&amp;hellip;", name: "Ellipsis", category: "Punctuation" },{ char: "←", entity: "&amp;larr;", name: "Left Arrow", category: "Arrows" },{ char: "→", entity: "&amp;rarr;", name: "Right Arrow", category: "Arrows" },{ char: "↑", entity: "&amp;uarr;", name: "Up Arrow", category: "Arrows" },{ char: "↓", entity: "&amp;darr;", name: "Down Arrow", category: "Arrows" },{ char: "«", entity: "&amp;laquo;", name: "Left Double Quote", category: "Quotes" },{ char: "»", entity: "&amp;raquo;", name: "Right Double Quote", category: "Quotes" },{ char: "×", entity: "&amp;times;", name: "Multiply", category: "Math" },{ char: "÷", entity: "&amp;divide;", name: "Divide", category: "Math" },{ char: "±", entity: "&amp;plusmn;", name: "Plus-Minus", category: "Math" },{ char: "°", entity: "&amp;deg;", name: "Degree", category: "Math" },{ char: "€", entity: "&amp;euro;", name: "Euro", category: "Currency" },{ char: "£", entity: "&amp;pound;", name: "Pound", category: "Currency" },{ char: "¥", entity: "&amp;yen;", name: "Yen", category: "Currency" },{ char: "&", entity: "&amp;amp;", name: "Ampersand", category: "Symbols" },{ char: "<", entity: "&amp;lt;", name: "Less Than", category: "Symbols" },{ char: ">", entity: "&amp;gt;", name: "Greater Than", category: "Symbols" },{ char: "“”", entity: "&amp;quot;", name: "Double Quote", category: "Quotes" },{ char: "'", entity: "&amp;apos;", name: "Single Quote", category: "Quotes" },{ char: " ", entity: "&amp;nbsp;", name: "Non-Breaking Space", category: "Punctuation" }];const decodeEntity = (s) => s.replace(/&amp;/g, "&");const search = root.querySelector("#entitySearch").value.trim().toLowerCase();const filtered = search? entities.filter((e) =>e.name.toLowerCase().includes(search) ||e.category.toLowerCase().includes(search) ||e.entity.toLowerCase().includes(search)): entities;let html;if (!search) {const groups = {};entities.forEach((e) => {if (!groups[e.category]) groups[e.category] = [];groups[e.category].push(e);});html = Object.entries(groups).map(([cat, items]) => `<div class="entity-category"><h4>${htmlEscape(cat)}</h4><table>${items.map((e) => `<tr class="entity-row" data-entity="${attrEscape(decodeEntity(e.entity))}"><td class="entity-char">${e.char}</td><td class="entity-code">${e.entity}</td><td class="entity-name">${htmlEscape(e.name)}</td></tr>`).join("")}</table></div>`).join("");} else {html = `<table>${filtered.map((e) => `<tr class="entity-row" data-entity="${attrEscape(decodeEntity(e.entity))}"><td class="entity-char">${e.char}</td><td class="entity-code">${e.entity}</td><td class="entity-name">${htmlEscape(e.name)}</td></tr>`).join("")}</table>`;}const preview = root.querySelector("[data-role='preview']");if (!preview.dataset.entityReady) {preview.dataset.entityReady = "true";preview.addEventListener("click", (e) => {const row = e.target.closest(".entity-row");if (row && row.dataset.entity) {navigator.clipboard.writeText(row.dataset.entity).catch(() => {});}});}return { output: "", preview: html };}};